<?php
declare(strict_types=1);
if (PHP_SAPI!=='cli') exit(1);
$root=dirname(__DIR__,2);
require $root.'/app/services/TrafficRequestService.php';
require $root.'/app/services/ContentStudioService.php';
function check(bool $ok,string $message): void { if (!$ok) throw new RuntimeException($message); }
function reject(callable $action,string $message): void { try { $action(); } catch (RuntimeException|InvalidArgumentException $e) { return; } throw new RuntimeException($message); }
$config=require $root.'/env/env.production.php'; $db=$config['db'];
$pdo=new PDO('mysql:host='.$db['host'].';charset=utf8mb4',$db['user'],$db['pass'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);
$database='test_traffic_ops_'.bin2hex(random_bytes(6));
$pdo->exec('CREATE DATABASE `'.$database.'`');
try {
    $pdo->exec('USE `'.$database.'`');
    ContentStudioService::ensureSchema($pdo); TrafficRequestService::ensureSchema($pdo); TrafficRequestService::ensureSchema($pdo);
    $user=['name'=>'Cliente','email'=>'cliente@example.com'];
    $brief=['title'=>'Teste operacional','business_name'=>'Loja','destination_type'=>'external','destination_url'=>'https://example.com/oferta',
        'platform'=>'meta','objective'=>'Visitas','region'=>'Jundiai','language'=>'Portugues'];
    $id=TrafficRequestService::save($pdo,1,1,0,0,TrafficRequestService::payload($brief,$user),true,true);
    $revision=fn()=>(int)TrafficRequestService::find($pdo,$id)['revision'];
    TrafficRequestService::review($pdo,$id,9,$revision(),'reviewing','');
    TrafficRequestService::review($pdo,$id,9,$revision(),'prepared','');
    $campaign=(int)TrafficRequestService::find($pdo,$id)['campaign_id'];
    $plan=['platform'=>'google','objective'=>'Visitas ao site','region'=>'Jundiai e regiao','audience'=>'Moradores','placements'=>'Pesquisa',
        'ad_title'=>'Conheca a loja','ad_text'=>'Oferta de teste','creative_url'=>'https://example.com/material.png',
        'starts_at'=>date('Y-m-d'),'ends_at'=>date('Y-m-d',strtotime('+7 days')),'external_campaign_id'=>'campaign-123',
        'external_campaign_url'=>'https://example.com/campaign/123','evidence_url'=>'https://example.com/evidence/123'];
    $next=fn($state,$extra=[])=>TrafficOperationsService::transition($pdo,$id,9,$revision(),['operation_status'=>$state,'manual_confirmed'=>'1','operation_notes'=>'Teste manual',...$extra]);
    reject(fn()=>$next('platform_review'),'Etapa sem planejamento aceita');
    reject(fn()=>TrafficOperationsService::savePlan($pdo,$id,9,$revision(),[...$plan,'platform'=>'recommend']),'Plataforma nao definida aceita');
    reject(fn()=>TrafficOperationsService::savePlan($pdo,$id,9,$revision(),[...$plan,'creative_url'=>'javascript:alert(1)']),'Material inseguro aceito');
    reject(fn()=>TrafficOperationsService::savePlan($pdo,$id,9,$revision(),[...$plan,'ends_at'=>'2020-01-01']),'Periodo invalido aceito');
    TrafficOperationsService::savePlan($pdo,$id,9,$revision(),$plan);
    check(TrafficRequestService::find($pdo,$id)['platform']==='meta','Planejamento sobrescreveu preferencia do cliente');
    reject(fn()=>TrafficOperationsService::plan($pdo,$id,2),'Planejamento cruzado exposto');
    reject(fn()=>TrafficOperationsService::reports($pdo,$id,2),'Resultados cruzados expostos');
    reject(fn()=>$next('active'),'Veiculacao pulou revisao da plataforma');
    reject(fn()=>$next('platform_review',['manual_confirmed'=>'']),'Registro sem confirmacao aceito');
    TrafficRequestService::review($pdo,$id,9,$revision(),'reply','Duvida operacional');
    reject(fn()=>$next('platform_review'),'Etapa com conversa aberta aceita');
    TrafficRequestService::review($pdo,$id,9,$revision(),'close_conversation','');
    reject(fn()=>$next('platform_review'),'Envio a plataforma sem aprovacao aceito');
    TrafficApprovalService::offer($pdo,$id,9,$revision());
    $first=TrafficApprovalService::latest($pdo,$id,1);
    reject(fn()=>TrafficApprovalService::latest($pdo,$id,2),'Aprovacao de outro projeto exposta');
    reject(fn()=>TrafficApprovalService::decide($pdo,$id,2,1,$revision(),1,'approve','',true),'Projeto cruzado aprovou');
    reject(fn()=>TrafficApprovalService::offer($pdo,$id,9,$revision()),'Oferta duplicada aceita');
    reject(fn()=>TrafficApprovalService::decide($pdo,$id,1,1,$revision(),1,'approve','',false),'Aprovacao sem confirmacao aceita');
    reject(fn()=>TrafficApprovalService::decide($pdo,$id,1,1,$revision(),1,'request_changes','',false),'Ajustes sem mensagem aceitos');
    reject(fn()=>TrafficApprovalService::decide($pdo,$id,1,1,$revision()-1,1,'approve','',true),'Aprovacao com revisao antiga aceita');
    reject(fn()=>TrafficApprovalService::decide($pdo,$id,1,1,$revision(),99,'approve','',true),'Versao inexistente aprovada');
    TrafficApprovalService::decide($pdo,$id,1,1,$revision(),1,'request_changes','Prefiro outro texto.',false);
    check(TrafficRequestService::find($pdo,$id)['status']==='prepared','Ajustes do plano alteraram briefing ou andamento');
    TrafficOperationsService::savePlan($pdo,$id,9,$revision(),[...$plan,'ad_text'=>'Novo texto']);
    TrafficApprovalService::offer($pdo,$id,9,$revision());
    $version2=TrafficApprovalService::latest($pdo,$id);
    TrafficOperationsService::savePlan($pdo,$id,9,$revision(),$plan);
    check(TrafficApprovalService::latest($pdo,$id)['status']==='invalidated','Edicao pendente nao invalidou versao');
    reject(fn()=>TrafficApprovalService::decide($pdo,$id,1,1,$revision(),2,'approve','',true),'Versao substituida aprovada');
    TrafficApprovalService::offer($pdo,$id,9,$revision());
    TrafficRequestService::review($pdo,$id,9,$revision(),'reply','Confirme uma informacao.');
    reject(fn()=>TrafficApprovalService::decide($pdo,$id,1,1,$revision(),3,'approve','',true),'Aprovacao com conversa aberta aceita');
    TrafficRequestService::review($pdo,$id,9,$revision(),'close_conversation','');
    TrafficApprovalService::decide($pdo,$id,1,1,$revision(),3,'approve','',true);
    reject(fn()=>TrafficApprovalService::decide($pdo,$id,1,1,$revision(),3,'approve','',true),'Decisao duplicada aceita');
    TrafficOperationsService::savePlan($pdo,$id,9,$revision(),[...$plan,'external_campaign_id'=>'new-platform-id']);
    check(TrafficApprovalService::isApproved($pdo,TrafficRequestService::find($pdo,$id)),'Referencia operacional invalidou conteudo aprovado');
    check($pdo->query('SELECT snapshot FROM content_studio_traffic_approvals WHERE id='.(int)$first['id'])->fetchColumn()===$first['snapshot'],'Edicao alterou snapshot anterior');
    check($pdo->query('SELECT snapshot FROM content_studio_traffic_approvals WHERE id='.(int)$version2['id'])->fetchColumn()===$version2['snapshot'],'Edicao pendente alterou snapshot');
    $next('platform_review');
    $pdo->exec("UPDATE content_studio_traffic_approvals SET status='invalidated' WHERE request_id=$id AND version=3");
    reject(fn()=>$next('active'),'Primeira veiculacao sem aprovacao valida aceita');
    $pdo->exec("UPDATE content_studio_traffic_approvals SET status='approved' WHERE request_id=$id AND version=3");
    $next('platform_rejected');
    TrafficOperationsService::savePlan($pdo,$id,9,$revision(),[...$plan,'ad_text'=>'Texto corrigido']);
    reject(fn()=>$next('platform_review'),'Alteracao preservou autorizacao anterior');
    TrafficApprovalService::offer($pdo,$id,9,$revision());
    TrafficApprovalService::decide($pdo,$id,1,1,$revision(),4,'approve','',true);
    $next('platform_review'); $next('active');
    check($pdo->query('SELECT status FROM content_studio_campaigns WHERE id='.$campaign)->fetchColumn()==='active','Campanha e pedido divergentes');
    $started=TrafficOperationsService::plan($pdo,$id)['actual_started_at'];
    $finalPost=['delivery_summary'=>'Resultados conferidos; visitas nao medidas.','delivery_evidence_url'=>'https://example.com/final-report','delivery_confirmed'=>'1'];
    reject(fn()=>TrafficDeliveryService::finalize($pdo,$id,9,$revision(),$finalPost),'Entrega encerrada antes do termino');
    reject(fn()=>TrafficOperationsService::savePlan($pdo,$id,9,$revision(),$plan),'Planejamento em veiculacao editavel');
    $report=['report_date'=>date('Y-m-d'),'impressions'=>'1000','link_clicks'=>'50','visits'=>'','source'=>'Relatorio de teste Google',
        'report_evidence_url'=>'https://example.com/report','report_notes'=>'Dados do dia'];
    foreach (['-1','1.5','2147483648'] as $invalid) reject(fn()=>TrafficOperationsService::saveReport($pdo,$id,9,$revision(),[...$report,'link_clicks'=>$invalid]),'Metrica invalida aceita');
    reject(fn()=>TrafficOperationsService::saveReport($pdo,$id,9,$revision(),[...$report,'report_date'=>date('Y-m-d',strtotime('+1 day'))]),'Resultado futuro aceito');
    reject(fn()=>TrafficOperationsService::saveReport($pdo,$id,9,$revision(),[...$report,'report_date'=>'2020-01-01']),'Resultado fora da veiculacao aceito');
    reject(fn()=>TrafficOperationsService::saveReport($pdo,$id,9,$revision(),[...$report,'source'=>'']),'Fonte ausente aceita');
    TrafficOperationsService::saveReport($pdo,$id,9,$revision(),$report);
    $oldRevision=$revision();
    TrafficOperationsService::saveReport($pdo,$id,9,$revision(),[...$report,'link_clicks'=>'60']);
    reject(fn()=>TrafficOperationsService::saveReport($pdo,$id,9,$oldRevision,$report),'Revisao antiga sobrescreveu relatorio');
    $reports=TrafficOperationsService::reports($pdo,$id,1);
    check(count($reports)===1 && (int)$reports[0]['link_clicks']===60,'Atualizacao duplicou dia ou nao corrigiu metrica');
    check(TrafficOperationsService::totals($reports)===['impressions'=>1000,'link_clicks'=>60,'visits'=>null],'Visitas nao medidas viraram zero');
    $next('paused'); $next('active');
    check(TrafficOperationsService::plan($pdo,$id)['actual_started_at']===$started,'Retomada apagou inicio original');
    // Simulate an already-running legacy campaign without approval records.
    $pdo->exec('DELETE FROM content_studio_traffic_approvals WHERE request_id='.$id);
    $next('paused'); $next('active');
    $next('completed');
    check($pdo->query('SELECT status FROM content_studio_campaigns WHERE id='.$campaign)->fetchColumn()==='finished','Conclusao nao sincronizou campanha');
    reject(fn()=>$next('active'),'Campanha concluida reativada');
    reject(fn()=>TrafficDeliveryService::report($pdo,$id,2),'Relatorio cruzado exposto');
    reject(fn()=>TrafficDeliveryService::finalize($pdo,$id,9,$revision(),[...$finalPost,'delivery_confirmed'=>'']),'Entrega sem confirmacao encerrada');
    reject(fn()=>TrafficDeliveryService::finalize($pdo,$id,9,$revision(),[...$finalPost,'delivery_summary'=>'']),'Entrega sem resumo encerrada');
    reject(fn()=>TrafficDeliveryService::finalize($pdo,$id,9,$revision(),[...$finalPost,'delivery_evidence_url'=>'javascript:alert(1)']),'Referencia final insegura aceita');
    reject(fn()=>TrafficDeliveryService::finalize($pdo,$id,9,$revision()-1,$finalPost),'Encerramento antigo aceito');
    $pdo->exec('UPDATE content_studio_traffic_requests SET conversation_open=1 WHERE id='.$id);
    reject(fn()=>TrafficDeliveryService::finalize($pdo,$id,9,$revision(),$finalPost),'Entrega com conversa aberta encerrada');
    $pdo->exec('UPDATE content_studio_traffic_requests SET conversation_open=0 WHERE id='.$id);
    $pdo->exec('DELETE FROM content_studio_traffic_reports WHERE request_id='.$id);
    reject(fn()=>TrafficDeliveryService::finalize($pdo,$id,9,$revision(),$finalPost),'Entrega sem resultados encerrada');
    TrafficOperationsService::saveReport($pdo,$id,9,$revision(),[...$report,'link_clicks'=>'60']);
    $partial=TrafficDeliveryService::report($pdo,$id,1);
    check($partial['delivery']===null && $partial['data']['coverage']['known']['visits']===0,'Cobertura inventou visitas');
    check(!isset($partial['data']['request']['contact_email']),'Relatorio expôs contato da conta');
    TrafficDeliveryService::finalize($pdo,$id,9,$revision(),$finalPost);
    $final=TrafficDeliveryService::report($pdo,$id,1);
    check($final['delivery'] && $final['data']['totals']['link_clicks']===60,'Relatorio final nao preservou totais');
    check(hash('sha256',$final['delivery']['snapshot'])===$final['delivery']['fingerprint'],'Hash final incorreto');
    reject(fn()=>TrafficDeliveryService::finalize($pdo,$id,9,$revision(),$finalPost),'Entrega encerrada novamente');
    reject(fn()=>TrafficOperationsService::saveReport($pdo,$id,9,$revision(),$report),'Relatorio final sobrescrito');
    $pdo->exec('UPDATE content_studio_traffic_reports SET link_clicks=999 WHERE request_id='.$id);
    check(TrafficDeliveryService::report($pdo,$id,1)['data']['totals']['link_clicks']===60,'Consulta final recalculou snapshot');
    $pdo->exec("UPDATE content_studio_traffic_deliveries SET fingerprint=REPEAT('0',64) WHERE request_id=$id");
    reject(fn()=>TrafficDeliveryService::report($pdo,$id,1),'Snapshot inconsistente foi apresentado');
    $pdo->prepare('UPDATE content_studio_traffic_deliveries SET fingerprint=? WHERE request_id=?')->execute([$final['delivery']['fingerprint'],$id]);
    $csv=TrafficDeliveryService::csv([[...$report,'source'=>'=1+1','evidence_url'=>'https://example.com/report','notes'=>"\t=HYPERLINK(1)"]]);
    check(str_contains($csv,"'=1+1")&&str_contains($csv,"'\t=HYPERLINK(1)"),'CSV permite formulas');
    check(TrafficDeliveryService::coverage($final['data']['reports'])['known']['link_clicks']===1,'Cobertura nao conta dias medidos');
    $mixed=[...$final['data']['reports'],['report_date'=>date('Y-m-d',strtotime('+1 day')),'impressions'=>null,'link_clicks'=>null,'visits'=>0]];
    check(TrafficDeliveryService::coverage($mixed)===['days'=>2,'first_day'=>date('Y-m-d'),'last_day'=>date('Y-m-d',strtotime('+1 day')),'known'=>['impressions'=>1,'link_clicks'=>1,'visits'=>1]],'Cobertura parcial incorreta');
    check($pdo->query("SHOW TABLES LIKE 'project_wallet_movements'")->fetchColumn()===false,'Operacao criou estruturas financeiras');
    echo "PASS: planejamento, aprovacao, operacao, relatorios, cobertura, encerramento imutavel e CSV seguro sem financeiro.\n";
} finally { $pdo->exec('DROP DATABASE IF EXISTS `'.$database.'`'); }
